import React, { useRef, useEffect } from 'react';
import Application from "./Application";
import MenuBar from './MenuBar';
import { HighlightProvider } from './HighlightContext';
import { ZIndexProvider } from './ZIndexContext'; 
import { GlobalCanvas, SmoothScrollbar } from '@14islands/r3f-scroll-rig'
import '@14islands/r3f-scroll-rig/css'
import CRTScreenEffect from './CRTScreenEffect';


function Screen() {



    return(
        <>
            <div className='distortion'>
            <div className="halo-effect">
            <CRTScreenEffect />
            <ZIndexProvider>
             <MenuBar />
             <HighlightProvider>
             <Application title="app1" type="text" content="this is test content" initialPosition={{ x: 50, y: 50 }}/>
             <Application title="app2" type="imageWithText" content={{image:"./icon.png", content:"this is also test content"}}initialPosition={{ x: 150, y: 50 }} />
             </HighlightProvider>

            </ZIndexProvider>
            </div>
             </div>

        </>

    );
}

export default Screen;
